head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.search_yn = false;
scwin.isAlarm = true; // 알람 상태가 on/off인지 체크
scwin.isBondsTeam = false; // 채권상장공시팀인지 체크
scwin.alarmCnt = 0;
scwin.gMoveToPosition = 0;
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gDate;

// 주권공시처리현황

scwin.arrOPEN = [0, 1, 2];

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description 현재날짜 셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // 현재날짜 셋팅
    scwin.gDate = $c.ut.cGetToday("yyyymmdd");
    edt_SrchDay.setValue(scwin.gDate);
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    for (let i = 0; i < scwin.arrOPEN.length; i++) {
        $p.getComponentById("checkbox_OPEN" + scwin.arrOPEN[i]).setValue(1);
    }
};

/**
 * @method
 * @name startSearch
 * @description start Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.startSearch = function() {
    scwin.setAlarm();
    scwin.initSearch();
};

/**
 * @method
 * @name initSearch
 * @description init Search 처리
 * @returns {void}
 * @hidden N
 */
scwin.initSearch = function() {
    scwin.reload('N');
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @param {*} pReload pReload
 * @returns {void}
 * @hidden N
 */
scwin.reload = function(pReload) {
    fn_CheckCond(pReload);
    setTimeout("fn_Reload('Y')", 60000); // 1초 = 1000 , 30초 = 30000
    scwin.alarmCnt++;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !검색--;
사용자;
클릭-- > async function(pReload) {
    scwin.gDate = edt_SrchDay.getValue();
    await scwin.searchAlarm(pReload);
};

/**
 * @method
 * @name validCheck
 * @description valid Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    let a = 0;
    for (let i = 0; i < scwin.arrOPEN.length; i++) {
        if ($p.getComponentById("checkbox_OPEN" + scwin.arrOPEN[i]).checked) {
            a++;
        }
    }
    if (a === 0) {
        await $c.win.alert("열람상태를 선택해 주세요.");
        checkbox_OPEN0.focus();
        return false;
    }

    // 일자 체크
    if (edt_SrchDay.getValue().length < 8) {
        await $c.win.alert("일자를 올바르게 입력해 주세요.");
        edt_SrchDay.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name getCheckedOPEN
 * @description get Checked OPEN 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCheckedOPEN = function() {
    const text = "";
    for (let i = 0; i < scwin.arrOPEN.length; i++) {
        if ($p.getComponentById("checkbox_OPEN" + scwin.arrOPEN[i]).checked) {
            text.setValue(i + "");
            i = scwin.arrOPEN.length;
        }
    }
    return text;
};

/**
 * @method
 * @name checkboxOPEN
 * @description checkbox OPEN 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.checkboxOPEN = function(flag) {
    if (flag === "0") {
        // 전체
        if (checkbox_OPEN0.checked) {
            for (let i = 1; i < scwin.arrOPEN.length; i++) {
                $p.getComponentById("checkbox_OPEN" + scwin.arrOPEN[i]).setValue(1);
            }
        } else {
            for (let i = 1; i < scwin.arrOPEN.length; i++) {
                $p.getComponentById("checkbox_OPEN" + scwin.arrOPEN[i]).setValue(0);
            }
        }
    } else {
        let a = 0;
        for (let i = 1; i < scwin.arrOPEN.length; i++) {
            if (!$p.getComponentById("checkbox_OPEN" + scwin.arrOPEN[i]).checked) {
                a++;
            }
        }
        if (a === 0) {
            checkbox_OPEN0.setValue(1);
        } else {
            checkbox_OPEN0.setValue(0);
        }
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);
    if (!await scwin.validCheck()) return;
    const sbmOptions = {
        id : "sbm_dts_DsclStudyList",
        action : "/MktActNotice.do",
        ref : "",
        target : "dts_DsclStudyList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchAlarm
 * @description search Alarm 처리
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchAlarm = async function(pReload) {
    if (!await scwin.validCheck()) return;
    const url = "/MktActNotice.do?method=listJntDisclsAlarm" + "&ACPT_DATE=" + scwin.gDate + "&EMP_NO=" + js_emp_no + "&READ_YN=" + scwin.getCheckedOPEN();
    if (pReload !== 'Y') {
        // 자동refresh일때는 로그 없앰
    }
    const sbmOptions = {
        id : "sbm_dts_Alarm",
        action : "&SCREN_ID=",
        ref : "",
        target : "dts_Alarm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclStudyList.getCellData(Number(obj), "ACPT_NO");
    // gDisclsDocNo  = dts_DsclStudyList.NameString(eval(obj),"DISCLS_DOC_NO");
    // gMainFormCd = dts_DsclStudyList.NameString(eval(obj),"FORM_CD");
    // gFormVer = dts_DsclStudyList.NameString(eval(obj),"FORM_VER");
    scwin.gIsurCd = dts_DsclStudyList.getCellData(Number(obj), "ISUR_CD");
    // gSndlocTpCd = dts_DsclStudyList.NameString(eval(obj),"SNDLOC_TP_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd+","+ gSndlocTpCd +"="+ gDisclsDocNo);

};

/**
 * @method
 * @name setAlarm
 * @description set Alarm 처리
 * @returns {void}
 * @hidden N
 */
scwin.setAlarm = function() {
    pnl_alert.style.display = 'none';
    if (js_dep_cd === "2430" || js_dep_cd === 'ZSYS') scwin.isBondsTeam = true;
    if (scwin.isBondsTeam) {
        pnl_bonds.style.display = '';
        pnl_alert.innerHTML = "<embed src='/common/form_procs_132.wav' name='alertSound1' autostart='false'>" + "<embed src='/common/form_procs_133.wav' name='alertSound2' autostart='false'>" + "<embed src='/common/form_procs_134.wav' name='alertSound3' autostart='false'>";
    } else {
        pnl_bonds.style.display = 'none';
    }
};

/**
 * @method
 * @name alarmCheck
 * @description alarm Check 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.alarmCheck = function(obj) {
    if (scwin.isAlarm) {
        // 알람 on 상태
        if (obj.getRowCount() > 0) {
            let soundTimeout = null;
            for (let i = 1; i <= obj.getRowCount(); i++) {
                const alarm_tp_cd = obj.getCellData(i, "ALARM_TP_CD");
                soundTimeout = setTimeout("playAlarm(" + alarm_tp_cd + ")", 5000 * i);
            }
            clearTimeout(soundTimeout); // 쿼리에서 데이터 한줄 추가해서 들고오도록 함(마지막 알림 안나옴)

        }
    }
};

/**
 * @method
 * @name playAlarm
 * @description play Alarm 처리
 * @param {Number} n n
 * @returns {void}
 * @hidden N
 */
scwin.playAlarm = function(n) {
    $p.getComponentById("alertSound" + n).play();
};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveHist
 * @description save Hist 처리
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveHist = async function(gAcptNo) {
    if (scwin.gAcptNo === null || scwin.gAcptNo === "") {
        return;
    } else {
        await scwin.setHeader();
        dts_Save.insertRow();
        dts_Save.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_Save.setCellData(1, "EMP_NO", js_emp_no);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/MktActNotice.do",
            ref : "dts_Save",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        await scwin.saveHist(scwin.gAcptNo); // 공시뷰어 열람이력 저장

        scwin.gMoveToPosition = row;
        await scwin.search();
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF10970.xml');
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    scwin.search_yn = true;
    fn_CheckCond('N');
};

/**
 * @method
 * @name dts_Alarm_OnLoadError
 * @description dts_Alarm 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Alarm_OnLoadError = async function() {
    await $c.win.alert(dts_Alarm);
};

/**
 * @method
 * @name dts_Alarm_OnLoadCompleted
 * @description dts_Alarm 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Alarm_OnLoadCompleted = async function(rowcount) {
    if (scwin.isBondsTeam) scwin.alarmCheck(dts_Alarm);

    // if(dts_Alarm.CountRow > 1 || alarmCnt <= 1) {
    await scwin.search();
    // }

};

/**
 * @method
 * @name dts_DsclStudyList_OnLoadError
 * @description dts_DsclStudyList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclStudyList_OnLoadError = async function() {
    await $c.win.alert(dts_DsclStudyList);
    scwin.gMoveToPosition = 0;
    scwin.search_yn = false;
};

/**
 * @method
 * @name dts_DsclStudyList_OnLoadCompleted
 * @description dts_DsclStudyList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclStudyList_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclStudyList.errorMsg) {
        await $c.win.alert(dts_DsclStudyList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        dts_DsclStudyList.setRowPosition(scwin.gMoveToPosition, 0);
    }
    scwin.gMoveToPosition = 0;
    scwin.search_yn = false;
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF10970.xml', SCREN_PROCS_TP_CD_07);
    const file_name = "주권공시처리현황";
    const today = $c.ut.cGetToday('yyyymmddhhmmss');
    const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
    // grd_Grid.GridToExcel("주권공시처리현황", "", "8");

};

/**
 * @method
 * @name img_Cal_onclick
 * @description img_Cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    scwin.setCode();
    scwin.init();

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.startSearch();
};

/**
 * @method
 * @name chk_alarm_onclick
 * @description chk_alarm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_alarm_onclick = function() {
    if (chk_alarm.checked) {
        scwin.isAlarm = true;
    } else {
        scwin.isAlarm = false;
    }
};

/**
 * @method
 * @name checkbox_OPEN0_onclick
 * @description checkbox_OPEN0 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.checkbox_OPEN0_onclick = function() {
    scwin.checkboxOPEN(0);
};

/**
 * @method
 * @name checkbox_OPEN1_onclick
 * @description checkbox_OPEN1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.checkbox_OPEN1_onclick = function() {
    scwin.checkboxOPEN(1);
};

/**
 * @method
 * @name checkbox_OPEN2_onclick
 * @description checkbox_OPEN2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.checkbox_OPEN2_onclick = function() {
    scwin.checkboxOPEN(2);
};
